 const [error,setError]=useState(''),[busy,setBusy]=useState(false),[placed,setPlaced]=useState(null),[couponCode,setCouponCode]=useState(''),[coupon,setCoupon]=useState(null),[couponMessage,setCouponMessage]=useState(''),[couponBusy,setCouponBusy]=useState(false),[delivery,setDelivery]=useState(Number(import.meta.env.VITE_DELIVERY_CHARGE_BDT||100)),[freeShippingThreshold,setFreeShippingThreshold]=useState(3000),[paymentSettings,setPaymentSettings]=useState({}),[advanceMethod,setAdvanceMethod]=useState('bkash'),[advanceSender,setAdvanceSender]=useState(''),[advanceTransaction,setAdvanceTransaction]=useState('')
