function GoogleSignInButton({onSuccess,onError}){
 const [ready,setReady]=useState(false)
 useEffect(()=>{
  const clientId=import.meta.env.VITE_GOOGLE_CLIENT_ID
  if(!clientId)return
  let active=true
  const init=()=>{if(!active||!window.google?.accounts?.id)return;window.google.accounts.id.initialize({client_id:clientId,callback:response=>{if(response?.credential)onSuccess(response.credential);else onError('Google sign-in was not completed.')}});const root=document.getElementById('so-google-signin');if(root){window.google.accounts.id.renderButton(root,{theme:'outline',size:'large',shape:'pill',text:'continue_with',width:320});setReady(true)}}
  let script=document.querySelector('script[data-so-google]')
  if(window.google?.accounts?.id)init()
  else if(!script){script=document.createElement('script');script.src='https://accounts.google.com/gsi/client';script.async=true;script.defer=true;script.dataset.soGoogle='true';script.onload=init;document.head.appendChild(script)}
  else script.addEventListener('load',init)
  return()=>{active=false;script?.removeEventListener?.('load',init)}
 },[onSuccess,onError])
 if(!import.meta.env.VITE_GOOGLE_CLIENT_ID)return <p className="auth-config-note">Google sign-in will appear after Google OAuth is configured.</p>
 return <div className="google-signin-wrap"><div id="so-google-signin"/>{!ready&&<span className="muted">Google sign-in loading…</span>}</div>
}
